INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-000000000001','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','Comment s''appelle la Constitution actuelle de la France ?','La Constitution actuelle est celle de la Ve République, adoptée le 4 octobre 1958.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-000000000002','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','Comment s''appelle le texte qui énonce les droits et devoirs des personnes résidant en France ?','La Charte des droits et devoirs du citoyen français, établie en 2012, rappelle les principes fondamentaux et les valeurs essentielles de la République.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-000000000003','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','Concernant les droits individuels, quelle proposition est correcte ?','Les droits individuels (liberté, sûreté, propriété, libre expression, etc.) sont garantis à toute personne sur le territoire français, sans discrimination.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-000000000004','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','De quelle année date la Déclaration des droits de l''homme et du citoyen ?','La Déclaration des droits de l''homme et du citoyen a été adoptée le 26 août 1789, pendant la Révolution française. Elle a valeur constitutionnelle.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-000000000005','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','Lequel de ces droits est un droit fondamental ?','Le droit à la liberté, le droit à la sûreté, le droit à la propriété sont des droits fondamentaux inscrits dans la Déclaration de 1789.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-000000000006','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','Parmi ces textes, lequel garantit les droits et libertés en France ?','La Déclaration des droits de l''homme et du citoyen de 1789, intégrée au "bloc de constitutionnalité", garantit les droits et libertés fondamentales.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-000000000007','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','Qu''est-ce que la liberté d''expression ?','La liberté d''expression est le droit de dire, écrire ou publier ses opinions, dans le respect des lois (pas d''injures, de diffamation, d''incitation à la haine).','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-000000000008','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','Quel droit permet à une personne de se défendre devant la justice ?','Le droit à la défense (et le droit à un avocat) est un principe fondamental. Toute personne accusée a le droit d''être défendue, présumée innocente jusqu''à preuve du contraire.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-000000000009','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'NAT','CONNAISSANCE','Quel est le texte fondateur établissant en France les droits et les devoirs de chaque citoyen ?','La Déclaration des droits de l''homme et du citoyen de 1789 est le texte fondateur des droits et libertés en France. Elle reste intégrée à la Constitution actuelle.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-00000000000a','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','Quel texte a été adopté pendant la Révolution française ?','La Déclaration des droits de l''homme et du citoyen a été adoptée le 26 août 1789 par l''Assemblée nationale constituante, pendant la Révolution.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-00000000000b','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','Quelle liberté permet à une personne de ne pas avoir de religion ?','La liberté de conscience, garantie par la laïcité, permet de croire, de ne pas croire ou de changer de religion.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-00000000000c','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','Une femme peut avorter :','Le droit à l''interruption volontaire de grossesse (IVG) est garanti depuis la loi Veil de 1975. Il est inscrit dans la Constitution depuis 2024.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-00000000000d','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','MISE_SITUATION','Est-il toujours possible de divorcer ?','Oui, le divorce est légal en France depuis 1792. Toute personne mariée peut demander le divorce, selon des procédures définies par la loi.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-00000000000e','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','La peine de mort est :','La peine de mort a été abolie en France le 9 octobre 1981 par la loi Badinter. Son abolition est inscrite dans la Constitution depuis 2007.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-00000000000f','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'NAT','CONNAISSANCE','Concernant les limites aux libertés individuelles, quelle proposition est correcte ?','Les libertés individuelles ne sont jamais absolues : elles s''arrêtent là où commencent celles des autres, et sont encadrées par la loi pour protéger l''ordre public et autrui.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-000000000010','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','MISE_SITUATION','En France, est-il légal d''être marié à plusieurs personnes en même temps ?','Non. La polygamie est interdite en France. Le mariage est l''union de deux personnes seulement. La bigamie est un délit pénal.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-000000000011','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CSP','MISE_SITUATION','Faut-il réduire ses déchets ?','Oui, la réduction des déchets est un devoir citoyen pour protéger l''environnement, prévu par le Code de l''environnement. Le tri et le recyclage sont obligatoires.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-000000000012','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CSP','MISE_SITUATION','Jeter une bouteille dans la rue est :','Jeter ses déchets dans la rue est une infraction (dépôt sauvage). C''est puni par une amende pouvant aller jusqu''à 1500 euros.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-000000000013','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'NAT','CONNAISSANCE','Pourquoi les libertés individuelles peuvent-elles être limitées ?','Les libertés peuvent être limitées pour protéger l''ordre public, la sécurité, la santé ou les libertés d''autrui. Ces limites doivent être proportionnées et fixées par la loi.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-000000000014','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CSP','MISE_SITUATION','Que doit faire une personne en cas d''accident ?','L''assistance à personne en danger est une obligation légale. Il faut prévenir les secours (15 SAMU, 17 Police, 18 Pompiers, 112 numéro européen) et aider sans se mettre en danger.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-000000000015','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','Que permet la citoyenneté française ?','La citoyenneté française donne des droits (voter, être élu, exercer certaines fonctions) et des devoirs (respecter la loi, payer ses impôts, défense, jury d''assises).','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-000000000016','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CSP','CONNAISSANCE','Que risque une personne qui ne respecte pas la loi ?','Selon la gravité, les sanctions vont de l''amende à la prison. Toute infraction est jugée par un tribunal et peut entraîner des conséquences pénales et civiles.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-000000000017','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','Quel est le rôle de la gendarmerie ?','La gendarmerie assure la sécurité publique, principalement en zone rurale et périurbaine. Elle exerce des missions de police judiciaire et administrative, sous tutelle du ministère de l''Intérieur.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-000000000018','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CSP','CONNAISSANCE','Quel est le rôle de la police ?','La police nationale assure la sécurité des personnes et des biens, principalement en zone urbaine. Elle prévient et constate les infractions, fait respecter l''ordre public.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-000000000019','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','Qu''est-ce qu''une infraction ?','Une infraction est un comportement interdit par la loi et puni. Il en existe trois catégories : contraventions (les moins graves), délits, crimes (les plus graves).','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-00000000001a','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CSP','MISE_SITUATION','Comment peut-on réduire ses déchets ?','On peut réduire ses déchets en triant, recyclant, compostant les déchets organiques, achetant en vrac, évitant le suremballage et réparant plutôt que jetant.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-00000000001b','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','MISE_SITUATION','Déposer une machine à laver cassée sur le trottoir est :','Déposer un encombrant sur le trottoir sans demande préalable est interdit. Il faut prendre rendez-vous avec le service "encombrants" de la mairie ou se rendre en déchetterie.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-00000000001c','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'NAT','CONNAISSANCE','En quoi consiste la traite des êtres humains ?','La traite des êtres humains consiste à exploiter une personne (travail forcé, prostitution, esclavage...) par la contrainte. C''est un crime grave puni par la loi.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-00000000001d','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','MISE_SITUATION','Que doit faire une victime de violences ?','Une victime de violences peut contacter les secours (17 Police, 15 SAMU), porter plainte au commissariat ou à la gendarmerie, et appeler le 3919 (violences conjugales) ou 119 (enfance en danger).','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000000-0000-0000-0000-00000000001e','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','Quelle est l''infraction la plus grave ?','Les infractions sont classées en trois catégories par gravité croissante : contraventions, délits, crimes. Le crime (meurtre, viol...) est l''infraction la plus grave.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000001-0000-0000-0000-000000000001','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','Quel est le nom de la Constitution actuellement en vigueur en France ?','La Constitution actuelle est celle de la Ve République, adoptée en 1958 sous l''impulsion du général de Gaulle.','true','2026-05-27 17:40:29.919456+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000001-0000-0000-0000-000000000002','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','Quel document présente les droits et devoirs des personnes résidant en France ?','Le Livret du citoyen (et la Charte des droits et devoirs du citoyen français pour les naturalisations) présente les droits et devoirs essentiels des résidents en France.','true','2026-05-27 17:40:29.919456+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000001-0000-0000-0000-000000000003','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','Concernant les droits individuels, quelle affirmation est exacte ?','Les droits individuels (liberté, sûreté, propriété) sont reconnus à toute personne en France. Ils peuvent être limités par la loi pour protéger l''ordre public et les droits d''autrui.','true','2026-05-27 17:40:29.919456+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000001-0000-0000-0000-000000000004','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','En quelle année la Déclaration des droits de l''homme et du citoyen a-t-elle été adoptée ?','La Déclaration des droits de l''homme et du citoyen a été adoptée le 26 août 1789, pendant la Révolution française.','true','2026-05-27 17:40:29.919456+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000001-0000-0000-0000-000000000005','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','Parmi ces droits, lequel est considéré comme un droit fondamental ?','Le droit à la vie, à la liberté et à la sûreté sont des droits fondamentaux, reconnus notamment par la Déclaration de 1789 et la Constitution.','true','2026-05-27 17:40:29.919456+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000001-0000-0000-0000-000000000006','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','Parmi ces textes, lequel garantit les droits et libertés en France ?','La Constitution (préambule et bloc de constitutionnalité, incluant la DDHC de 1789) garantit les droits et libertés fondamentaux.','true','2026-05-27 17:40:29.919456+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000001-0000-0000-0000-000000000007','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','Que signifie la liberté d''expression en France ?','La liberté d''expression permet d''exprimer ses opinions par la parole, l''écrit ou l''image, dans les limites posées par la loi (interdiction de la diffamation, de l''incitation à la haine).','true','2026-05-27 17:40:29.919456+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000001-0000-0000-0000-000000000008','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','Quel droit permet de se défendre devant un tribunal en France ?','Le droit à un procès équitable inclut le droit à la défense : être assisté par un avocat, présenter sa version, contredire les preuves. C''est un droit fondamental.','true','2026-05-27 17:40:29.919456+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000001-0000-0000-0000-000000000009','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'NAT','CONNAISSANCE','Quel texte historique établit les droits et devoirs fondamentaux des citoyens en France ?','La Déclaration des droits de l''homme et du citoyen de 1789 est le texte fondateur. Elle est intégrée au bloc de constitutionnalité et a aujourd''hui valeur constitutionnelle.','true','2026-05-27 17:40:29.919456+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000001-0000-0000-0000-00000000000a','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','Quel texte fondateur a été adopté pendant la Révolution française ?','La Déclaration des droits de l''homme et du citoyen, adoptée le 26 août 1789, est le texte symbole de la Révolution française.','true','2026-05-27 17:40:29.919456+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000001-0000-0000-0000-00000000000b','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','Quelle liberté autorise une personne à ne pratiquer aucune religion ?','La liberté de conscience inclut le droit de ne pas croire (être athée, agnostique). Personne ne peut être forcé d''adhérer à une religion.','true','2026-05-27 17:40:29.919456+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000001-0000-0000-0000-00000000000c','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','Une femme peut-elle recourir à une interruption volontaire de grossesse (IVG) en France ?','Oui. L''IVG est légale en France depuis la loi Veil de 1975. Elle a été inscrite dans la Constitution en mars 2024 comme liberté fondamentale.','true','2026-05-27 17:40:29.919456+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000001-0000-0000-0000-00000000000d','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','MISE_SITUATION','Le divorce est-il toujours possible en France ?','Oui. Le divorce est légal en France depuis 1792 (avec interruption sous la Restauration). Plusieurs procédures existent : par consentement mutuel, pour faute, pour acceptation, pour altération définitive du lien conjugal.','true','2026-05-27 17:40:29.919456+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000001-0000-0000-0000-00000000000e','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','CONNAISSANCE','Quel est le statut de la peine de mort en France ?','La peine de mort est abolie en France depuis 1981 (loi du 9 octobre 1981, portée par Robert Badinter). L''abolition a été inscrite dans la Constitution en 2007.','true','2026-05-27 17:40:29.919456+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000001-0000-0000-0000-00000000000f','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'NAT','CONNAISSANCE','Que dit le droit français sur les limites possibles aux libertés individuelles ?','Les libertés individuelles ne sont pas absolues. Elles peuvent être limitées par la loi pour protéger l''ordre public, les droits d''autrui ou la sécurité nationale.','true','2026-05-27 17:40:29.919456+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000001-0000-0000-0000-000000000010','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CR','MISE_SITUATION','En France, est-il légal d''être marié à plusieurs personnes simultanément ?','Non. La polygamie est interdite par la loi française. Le mariage civil n''est valable qu''entre deux personnes. La polygamie est un délit et fait obstacle à la naturalisation.','true','2026-05-27 17:40:29.926748+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000001-0000-0000-0000-000000000011','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CSP','MISE_SITUATION','Est-il important de réduire la quantité de ses déchets au quotidien ?','Oui. Réduire ses déchets est un geste citoyen important pour protéger l''environnement et respecter le principe de développement durable, inscrit dans la Charte de l''environnement de 2004.','true','2026-05-27 17:40:29.926748+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000001-0000-0000-0000-000000000012','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CSP','MISE_SITUATION','Jeter une bouteille dans la rue est-il autorisé en France ?','Non. Jeter des déchets sur la voie publique est une infraction, punie d''une contravention. C''est aussi un manque de respect envers l''environnement et les autres.','true','2026-05-27 17:40:29.926748+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000001-0000-0000-0000-000000000013','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'NAT','CONNAISSANCE','Pour quelles raisons les libertés individuelles peuvent-elles être encadrées par la loi ?','Les libertés individuelles peuvent être limitées pour protéger l''ordre public, la sécurité, la santé publique, les droits d''autrui ou prévenir les atteintes à la dignité.','true','2026-05-27 17:40:29.926748+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f3000001-0000-0000-0000-000000000014','CIVIQUE','11111111-0000-0000-0000-000000000003',NULL,NULL,'CSP','MISE_SITUATION','Que doit faire toute personne présente sur les lieux d''un accident grave ?','Toute personne doit porter assistance à une personne en danger, ou au moins prévenir les secours (15, 17, 18, 112). Ne pas le faire constitue un délit de non-assistance à personne en danger.','true','2026-05-27 17:40:29.926748+02',NULL,'ACTIVE',NULL,NULL,NULL);
